    change_opacity: {
      color: EntryStatic.colorSet.block["default"].BRUSH,
      skeleton: 'basic',
      statements: [],
      params: [{
        type: 'Block',
        accept: 'string'
      }, {
        type: 'Indicator',
        img: 'block_icon/brush_03.png',
        size: 12
      }],
      events: {},
      def: {
        params: [{
          type: 'number',
          params: ['10']
        }, null],
        type: 'change_opacity'
      },
      paramsKeyMap: {
        VALUE: 0
      },
      "class": 'brush_opacity',
      isNotFor: ['textBox'],
      func: function func(sprite, script) {
        var opacity = script.getNumberValue('VALUE', script);
        if (!sprite.brush || !sprite.shapes.length) {
          Entry.setBasicBrush(sprite);
          sprite.brush.stop = true;
        }
        opacity = Entry.adjustValueWithMaxMin(sprite.brush.opacity + opacity, 0, 100);
        if (sprite.brush) {
          sprite.brush.opacity = opacity;
          sprite.brush.endStroke();
          var rgb = sprite.brush.rgb;
          sprite.brush.beginStroke("rgba(".concat(rgb.r, ",").concat(rgb.g, ",").concat(rgb.b, ",").concat(sprite.brush.opacity / 100, ")"));
          sprite.brush.moveTo(sprite.getX(), sprite.getY() * -1);
        }
        return script.callReturn();
      },
      syntax: {
        js: [],
        py: ['']
      }
    },
