    sound_something_wait: {
      color: EntryStatic.colorSet.block["default"].SOUND,
      skeleton: 'basic',
      statements: [],
      params: [{
        type: 'DropdownDynamic',
        value: null,
        menuName: 'sounds',
        fontSize: 11
      }, {
        type: 'Indicator',
        img: 'block_icon/sound_03.png',
        size: 12
      }],
      events: {},
      def: {
        params: [null, null],
        type: 'sound_something_wait'
      },
      paramsKeyMap: {
        VALUE: 0
      },
      "class": 'sound',
      isNotFor: [],
      func: function func(sprite, script) {
        if (!script.isPlay) {
          script.isPlay = true;
          script.playState = 1;
          var soundId = script.getField('VALUE', script);
          var sound = sprite.parent.getSound(soundId);
          var sounds = sprite.parent.sounds;
          var isExist = Entry.isExist(soundId, 'id', sounds);
          if (isExist) {
            var instance = Entry.Utils.playSound(soundId);
            Entry.Utils.addSoundInstances(instance);
            setTimeout(function () {
              script.playState = 0;
            }, sound.duration * 1000);
          }
          return script;
        } else if (script.playState === 1) {
          return script;
        } else {
          delete script.playState;
          delete script.isPlay;
          return script.callReturn();
        }
      },
      syntax: {
        js: [],
        py: ['']
      }
    },
