    pyocoding_change_analog_to_temperature_tc_value: {
      color: EntryStatic.colorSet.block["default"].HARDWARE,
      outerLine: EntryStatic.colorSet.block.darken.HARDWARE,
      skeleton: 'basic_string_field',
      statements: [],
      events: {},
      params: [{
        "type": "Block",
        "accept": "string"
      }],
      def: {
        params: [{
          "type": "text",
          "params": ["0"]
        }, null],
        "type": "pyocoding_change_analog_to_temperature_tc_value"
      },
      isNotFor: ['0uboard'],
      "class": "ext",
      paramsKeyMap: {
        "VALUE": 0
      },
      func: function func(sprite, script) {
        var R1 = 10000;
        var logR2, R2, T, Tc, Tf;
        var c1 = 1.106836861e-03,
          c2 = 2.384641754e-04,
          c3 = 0.6507394466e-07;
        var Vo = script.getNumberValue("VALUE");
        R2 = R1 * (4095.0 / Vo - 1.0);
        logR2 = Math.log(R2);
        T = 1.0 / (c1 + c2 * logR2 + c3 * logR2 * logR2 * logR2);
        Tc = T - 273.15; //섭씨
        //Tf = (Tc * 9.0)/ 5.0 + 32.0; //화씨

        // Print the result to the console
        //console.log("vo:",Vo,"Tc:",Tc);

        // You can return the value in Fahrenheit as well
        return Tc;
      }
    },
