    CloverSEntry1_get_analog_value_map: {
      color: EntryStatic.colorSet.block["default"].HARDWARE,
      outerLine: EntryStatic.colorSet.block.darken.HARDWARE,
      fontColor: '#fff',
      skeleton: 'basic_string_field',
      statements: [],
      params: [{
        type: 'Dropdown',
        options: [["1", 0], ["2", 1]],
        fontSize: 12,
        bgColor: EntryStatic.colorSet.block.darken.HARDWARE,
        arrowColor: EntryStatic.colorSet.arrow["default"].HARDWARE
      }, {
        type: 'Block',
        accept: 'number'
      }, {
        type: 'Block',
        accept: 'number'
      }, {
        type: 'Block',
        accept: 'number'
      }, {
        type: 'Block',
        accept: 'number'
      }],
      events: {},
      def: {
        params: [0, {
          type: 'number',
          params: ['0']
        }, {
          type: 'number',
          params: ['1023']
        }, {
          type: 'number',
          params: ['0']
        }, {
          type: 'number',
          params: ['100']
        }],
        type: 'CloverSEntry1_get_analog_value_map'
      },
      paramsKeyMap: {
        PORT: 0,
        VALUE2: 1,
        VALUE3: 2,
        VALUE4: 3,
        VALUE5: 4
      },
      "class": 'getBlock',
      isNotFor: ['CloverSEntry1'],
      func: function func(sprite, script) {
        var port = script.getField('PORT', script);
        var ANALOG = Entry.hw.portData.ANALOG;
        var value2 = script.getNumberValue('VALUE2', script);
        var value3 = script.getNumberValue('VALUE3', script);
        var value4 = script.getNumberValue('VALUE4', script);
        var value5 = script.getNumberValue('VALUE5', script);
        var org_value;
        var org_percent;
        var org_range;
        var dest_range;
        var dest_value;
        var swap = 0;
        if (value2 > value3) {
          swap = value2;
          value2 = value3;
          value3 = swap;
        }
        if (value4 > value5) {
          swap = value4;
          value4 = value5;
          value5 = swap;
        }
        org_value = ANALOG[port] - value2;
        org_range = value3 - value2;
        dest_range = value5 - value4;
        if (org_range <= 0) {
          return 0;
        }
        if (dest_range <= 0) {
          return 0;
        }
        if (org_value <= 0) {
          return 0;
        }
        org_percent = org_value / org_range * 100;
        dest_value = value4 + dest_range * (org_percent / 100);
        if (dest_value < value4) {
          dest_value = value4;
        }
        if (dest_value > value5) {
          dest_value = value5;
        }
        return dest_value;
      },
      syntax: {
        js: [],
        py: []
      }
    },
