    // 3. 쉬운주행
    LineCodingLineEasy: {
      color: EntryStatic.colorSet.block["default"].HARDWARE,
      outerLine: EntryStatic.colorSet.block.darken.HARDWARE,
      fontColor: '#fff',
      skeleton: 'basic',
      statements: [],
      params: [{
        type: 'Block',
        accept: 'string'
      }, {
        type: 'Indicator',
        img: 'block_icon/hardware_icon.svg',
        size: 12
      }],
      events: {},
      def: {
        params: [{
          type: 'LineCodingEasylineList'
        }, null],
        type: 'LineCodingLineEasy'
      },
      paramsKeyMap: {
        VALUE: 0
      },
      "class": 'LineCoding_EASY',
      isNotFor: ['LineCoding'],
      func: function func(sprite, script) {
        var value = script.getNumberValue('VALUE');
        if (LineOneFlag == 1) {
          if (LineSaveFlag == 1) {
            ++LineNum;
          }
          LineInit = Entry.hw.portData.DIGITAL[0];
          if (!Entry.hw.sendQueue.SET) {
            Entry.hw.sendQueue.SET = {};
          }
          Entry.hw.sendQueue.SET[parseInt(LineNum, 10)] = {
            type: Entry.LineCoding.sensorTypes.LINE_EASY,
            data: value,
            time: new Date().getTime()
          };
          LineOneFlag = 0;
        }
        if (Entry.hw.portData.DIGITAL[0] == LineInit && LineSaveFlag == 0) {
          return script;
        } else {
          LineOneFlag = 1;
          return script.callReturn();
        }
      },
      syntax: {
        js: [],
        py: []
      }
    },
    // 4. 쉬운주행 설정
    LineCodingEasySet: {
      color: EntryStatic.colorSet.block["default"].HARDWARE,
      outerLine: EntryStatic.colorSet.block.darken.HARDWARE,
      fontColor: '#fff',
      skeleton: 'basic',
      statements: [],
      params: [{
        type: 'Block',
        accept: 'string'
      }, {
        type: 'Block',
        accept: 'string'
      }, {
        type: 'Indicator',
        img: 'block_icon/hardware_icon.svg',
        size: 12
      }],
      events: {},
      def: {
        params: [{
          type: 'LineCodingEasySetList'
        }, {
          type: 'number',
          params: ['20']
        }, null],
        type: 'LineCodingEasySet'
      },
      paramsKeyMap: {
        PORT: 0,
        NUM: 1
      },
      "class": 'LineCoding_EASY',
      isNotFor: ['LineCoding'],
      func: function func(sprite, script) {
        var port = script.getNumberValue('PORT', script);
        var num = script.getNumberValue('NUM', script);
        if (!script.isStart) {
          if (LineSaveFlag == 1) {
            ++LineNum;
          }
          if (!Entry.hw.sendQueue.SET) {
            Entry.hw.sendQueue.SET = {};
          }
          script.isStart = true;
          script.timeFlag = 1;
          if (port == 55) {
            Entry.hw.sendQueue.SET[parseInt(LineNum, 10)] = {
              type: Entry.LineCoding.sensorTypes.LINE_FW_SPEED,
              data: [num],
              time: new Date().getTime()
            };
          } else {
            Entry.hw.sendQueue.SET[parseInt(LineNum, 10)] = {
              type: Entry.LineCoding.sensorTypes.LINE_TURN_SPEED,
              data: [num],
              time: new Date().getTime()
            };
          }
          setTimeout(function () {
            script.timeFlag = 0;
          }, 0.1);
          return script;
        } else if (script.timeFlag === 1) {
          return script;
        } else {
          delete script.timeFlag;
          delete script.isStart;
          Entry.engine.isContinue = false;
          return script.callReturn();
        }
      },
      syntax: {
        js: [],
        py: []
      }
    },
