    //  스피커 멜로디
    LineCodingMelody: {
      color: EntryStatic.colorSet.block["default"].HARDWARE,
      outerLine: EntryStatic.colorSet.block.darken.HARDWARE,
      fontColor: '#fff',
      skeleton: 'basic',
      statements: [],
      params: [{
        type: 'Block',
        accept: 'string'
      }, {
        type: 'Block',
        accept: 'string'
      }, {
        type: 'Block',
        accept: 'string'
      }, {
        type: 'Indicator',
        img: 'block_icon/hardware_icon.svg',
        size: 12
      }],
      events: {},
      def: {
        params: [{
          type: 'LineCodingOctaveList'
        }, {
          type: 'LineCodingToneList'
        }, {
          type: 'text',
          params: ['0.25']
        }, null],
        type: 'LineCodingMelody'
      },
      paramsKeyMap: {
        OCTAVE: 0,
        NOTE: 1,
        DURATION: 2
      },
      "class": 'LineCoding_LINE2',
      isNotFor: ['LineCoding'],
      func: function func(sprite, script) {
        var duration2 = script.getNumberValue('DURATION');
        var octave = script.getNumberValue('OCTAVE');
        var value2 = 0;
        if (LineSaveFlag == 1) {
          ++LineNum;
        }
        if (!script.isStart) {
          var note = script.getValue('NOTE');
          if (!Entry.Utils.isNumber(note)) {
            note = Entry.LineCoding.toneTable[note];
          }
          if (note < 0) {
            note = 0;
          } else if (note > 12) {
            note = 12;
          }
          if (duration2 < 0) {
            duration2 = 0;
          }
          if (!Entry.hw.sendQueue.SET) {
            Entry.hw.sendQueue.SET = {};
          }
          if (duration2 === 0) {
            // 음 길이가 0 이면
            Entry.hw.sendQueue.SET[parseInt(LineNum, 10)] = {
              type: Entry.LineCoding.sensorTypes.TONE,
              data: 0,
              time: new Date().getTime()
            };
            return script.callReturn();
          }
          if (octave < 0) {
            octave = 0;
          } else if (octave > 4) {
            octave = 4;
          }
          if (note != 0) {
            value2 = Entry.LineCoding.toneMap[note][octave];
          }
          if (duration2 > 30) {
            duration2 = 30;
          }
          duration2 = duration2 * 1000;
          script.isStart = true;
          // 출력 시작 플래그 셋
          script.timeFlag = 1;
          // 시간플래그 셋

          Entry.hw.sendQueue.SET[parseInt(LineNum, 10)] = {
            type: Entry.LineCoding.sensorTypes.TONE,
            data: {
              value: value2,
              duration: duration2
            },
            time: new Date().getTime()
          };
          setTimeout(function () {
            script.timeFlag = 0;
          }, duration2 + 32);
          return script;
        } else if (script.timeFlag === 1) {
          return script;
        } else {
          delete script.timeFlag;
          delete script.isStart;
          Entry.hw.sendQueue.SET[parseInt(LineNum, 10)] = {
            type: Entry.LineCoding.sensorTypes.TONE,
            data: 0,
            time: new Date().getTime()
          };
          Entry.engine.isContinue = false;
          return script.callReturn();
        }
      },
      syntax: {
        js: [],
        py: []
      }
    },
