AlbertAiRobot.prototype.moveToOnBoard = function (script) {
  this.__setModule();
  if (!script.isStart) {
    script.isStart = true;
    script.isMoving = true;
    this.__cancelNavigation();
    this.__cancelMotion();
    var toward = script.getField('TOWARD');
    var x = script.getNumberValue('X');
    var y = script.getNumberValue('Y');
    x = parseInt(x);
    y = parseInt(y);
    var navi = this.__getNavigator();
    if (typeof x == 'number' && typeof y == 'number' && x >= 0 && y >= 0) {
      var motoring = this.motoring;
      motoring.leftWheel = 0;
      motoring.rightWheel = 0;
      this.__setPulse(0);
      this.__setMotion(0, 0, 0, 0, 0);
      navi.setBackward(toward == 'BACKWARD');
      navi.moveTo(x, y);
      this.navigationCallback = function () {
        script.isMoving = false;
      };
    }
    return script;
  } else if (script.isMoving) {
    return script;
  } else {
    delete script.isStart;
    delete script.isMoving;
    Entry.engine.isContinue = false;
    return script.callReturn();
  }
};
AlbertAiRobot.prototype.setOrientationToOnBoard = function (script) {
  this.__setModule();
  if (!script.isStart) {
    script.isStart = true;
    script.isMoving = true;
    this.__cancelNavigation();
    this.__cancelMotion();
    var degree = script.getNumberValue('DEGREE');
    degree = parseInt(degree);
    if (typeof degree == 'number') {
      var navi = this.__getNavigator();
      var motoring = this.motoring;
      motoring.leftWheel = 0;
      motoring.rightWheel = 0;
      this.__setPulse(0);
      this.__setMotion(0, 0, 0, 0, 0);
      navi.setBackward(false);
      navi.turnTo(degree);
      this.navigationCallback = function () {
        script.isMoving = false;
      };
    }
    return script;
  } else if (script.isMoving) {
    return script;
  } else {
    delete script.isStart;
    delete script.isMoving;
    Entry.engine.isContinue = false;
    return script.callReturn();
  }
};
