AlbertAiRobot.prototype.playSound = function (script) {
  this.__setModule();
  this.__cancelNote();
  this.__cancelSound();
  var sound = script.getField('SOUND');
  var count = script.getNumberValue('COUNT');
  sound = this.__SOUNDS[sound];
  count = parseInt(count);
  this.motoring.buzzer = 0;
  this.motoring.note = 0;
  if (sound && count) {
    this.__runSound(sound, count);
  } else {
    this.__runSound(0);
  }
  return script.callReturn();
};
AlbertAiRobot.prototype.playSoundUntil = function (script) {
  this.__setModule();
  if (!script.isStart) {
    script.isStart = true;
    script.isPlaying = true;
    this.__cancelNote();
    this.__cancelSound();
    var sound = script.getField('SOUND');
    var count = script.getNumberValue('COUNT');
    sound = this.__SOUNDS[sound];
    count = parseInt(count);
    this.motoring.buzzer = 0;
    this.motoring.note = 0;
    if (sound && count) {
      this.__runSound(sound, count);
      this.soundCallback = function () {
        script.isPlaying = false;
      };
    } else {
      this.__runSound(0);
      script.isPlaying = false;
    }
    return script;
  } else if (script.isPlaying) {
    return script;
  } else {
    delete script.isStart;
    delete script.isPlaying;
    Entry.engine.isContinue = false;
    return script.callReturn();
  }
};
