    bitbrick_turn_on_color_led_by_value: {
      color: EntryStatic.colorSet.block["default"].HARDWARE,
      outerLine: EntryStatic.colorSet.block.darken.HARDWARE,
      skeleton: 'basic',
      statements: [],
      params: [{
        type: 'Block',
        accept: 'string'
      }, {
        type: 'Indicator',
        img: 'block_icon/hardware_icon.svg',
        size: 12
      }],
      events: {},
      def: {
        params: [{
          type: 'text',
          params: ['0']
        }, null],
        type: 'bitbrick_turn_on_color_led_by_value'
      },
      paramsKeyMap: {
        VALUE: 0
      },
      "class": 'led',
      isNotFor: ['bitbrick'],
      func: function func(sprite, script) {
        var value = script.getNumberValue('VALUE');
        var red, green, blue;
        value = value % 200;
        if (value < 67) {
          red = 200 - value * 3;
          green = value * 3;
          blue = 0;
        } else if (value < 134) {
          value = value - 67;
          red = 0;
          green = 200 - value * 3;
          blue = value * 3;
        } else if (value < 201) {
          value = value - 134;
          red = value * 3;
          green = 0;
          blue = 200 - value * 3;
        }
        Entry.hw.sendQueue['LEDR'] = red;
        Entry.hw.sendQueue['LEDG'] = green;
        Entry.hw.sendQueue['LEDB'] = blue;
        return script.callReturn();
      },
      syntax: {
        js: [],
        py: ['Bitbrick.color_led_by_value(%1)']
      }
    },
