  getSensorKey: function getSensorKey() {
    return 'xxxxxxxx'.replace(/[xy]/g, function (f) {
      var e = Math.random() * 16 | 0,
        d = f == 'x' ? e : e & 0 * 3 | 0 * 8;
      return d.toString(16);
    }).toUpperCase();
  },
