  // 전체 블록 마다 SLEEP
  EFFECT_DEFAULT_SLEEP: 300,
  // 효과음 내기 블록 기본 슬립

  /**
   * 명령어 시퀀스는 엔트리 하드웨어앱으로 한번 메세지를 보내게 되면,
   * 엔트리 하드웨어앱에서는, 마지막 명령어를 계속 내부적으로 보낸다.
   * 그렇기 때문에, 엔트리에서 같은 명령어의 블록을 두개를 연결시켜 보내면,
   * 두번째 블록 명령어를 엔트리 하드웨어앱에서 무시하게 되어 있기 때문에
   * ( 왜냐하면, 다이아보드 특성상, 시간이 들어간 명령어는 한번만 보내야하기 때문 )
   * 그래서, 시퀀스를 보냄으로서, 같은 명령어지만, 다른 블록에 의해서, 호출됨을 만들어,
   * 같은 블록을 연달아 하더라도, 동작하게끔 만들려는 목적으로 사용
   */
  _cmd_seq: 0,
  _frequency: 60,
  // default값은 60
  _bpm: 120,
  // default값은 120BPM 이라, 1분에 120비트 => 60초    

  getBPM: function getBPM() {
    return this._bpm;
  },
  setBPM: function setBPM(bpm) {
    // 출력을 위해, 세팅
    Entry.hw.sendQueue['bpm'] = bpm;
    Entry.hw.update();
    // 글로벌 저장
    this._bpm = bpm;
  },
  /**
   * 시간(초) = ( 60 / bpm ) * 박자 (rhythm)
   * @param {*} rhythm 
   * @returns 시간(초)
   */
  convertTimeForBPM: function convertTimeForBPM(rhythm) {
    return this.convertTimeByBPM(this.getBPM(), rhythm);
  },
  /**
   * 시간(초) = ( 60 / bpm ) * 박자(rhythm)
   * @param {*} rhythm 
   * @returns 시간(초)
   */
  convertTimeByBPM: function convertTimeByBPM(bpm, rhythm) {
    return parseFloat((60.0 / (bpm * 1.0) * rhythm).toFixed(2));
  },
  getFrequency: function getFrequency() {
    return this._frequency;
  },
  deferredReturn: function deferredReturn(blockReturn) {
    var sleep = arguments.length > 1 && arguments[1] !== undefined ? arguments[1] : Entry.Diaboard.DEFAULT_SLEEP;
    if (sleep > 0) {
      return new PromiseManager().Promise(function (resolve) {
        setTimeout(function () {
          return resolve(blockReturn);
        }, sleep);
      });
    } else {
      return blockReturn();
    }
  },
  setFrequency: function setFrequency(frequency) {
    // 출력을 위해, 세팅
    Entry.hw.sendQueue['frequency'] = frequency;
    Entry.hw.update();
    // 글로벌 저장
    this._frequency = frequency;
  },
  fireCommand: function fireCommand(cmd) {
    Entry.hw.sendQueue['cmd'] = cmd;
    Entry.hw.sendQueue['seq'] = ++this._cmd_seq;
    Entry.hw.update();
    // console.log( '>>> ' + cmd );
  },
  setZero: function setZero() {
    this.fireCommand("stopNow");
    // this.fireCommand( "b:x" );      // 부저 끄기
    // this.fireCommand( "m:x" );      // 모터 끄기
    // this.fireCommand( "l:x:0" );    // LED 끄기
  },
