    diaboard_button_pressed: {
      color: EntryStatic.colorSet.block["default"].HARDWARE,
      outerLine: EntryStatic.colorSet.block.darken.HARDWARE,
      fontColor: '#fff',
      skeleton: 'basic_boolean_field',
      statements: [],
      params: [{
        type: 'Dropdown',
        options: options_DIABOARD_button1,
        value: 'left',
        fontSize: 11,
        bgColor: EntryStatic.colorSet.block.darken.HARDWARE,
        arrowColor: EntryStatic.colorSet.arrow["default"].HARDWARE
      }, {
        type: 'Dropdown',
        options: options_DIABOARD_button2,
        value: 'pressed',
        fontSize: 11,
        bgColor: EntryStatic.colorSet.block.darken.HARDWARE,
        arrowColor: EntryStatic.colorSet.arrow["default"].HARDWARE
      }],
      events: {},
      def: {
        params: [null, null],
        type: 'diaboard_button_pressed'
      },
      paramsKeyMap: {
        PORT: 0,
        STATUS: 1
      },
      "class": 'condition',
      isNotFor: ['diaboard'],
      func: function func(sprite, script) {
        var port = script.getStringField('PORT');
        var status = script.getStringField('STATUS');
        var leftButton = Entry.hw.portData['S1'] == 'T' ? true : false;
        var rightButton = Entry.hw.portData['S2'] == 'T' ? true : false;
        var buttonStatus = status == 'pressed' ? true : false;
        if (port == 'all') {
          // all
          return leftButton == buttonStatus && rightButton == buttonStatus;
        } else if (port == 'left') {
          return leftButton == buttonStatus;
        } else if (port == 'right') {
          return rightButton == buttonStatus;
        }
        return false;
      },
      syntax: {
        js: [],
        py: ['Diaboard.button_pressed(%1,%2)']
      }
    },
