    diaboard_sensor_condition: {
      color: EntryStatic.colorSet.block["default"].HARDWARE,
      outerLine: EntryStatic.colorSet.block.darken.HARDWARE,
      fontColor: '#fff',
      skeleton: 'basic_boolean_field',
      statements: [],
      params: [{
        type: 'Dropdown',
        fontSize: 11,
        bgColor: EntryStatic.colorSet.block.darken.HARDWARE,
        arrowColor: EntryStatic.colorSet.arrow["default"].HARDWARE,
        options: options_DIABOARD_sensor,
        value: 'ir'
      }, {
        type: 'Dropdown',
        fontSize: 11,
        bgColor: EntryStatic.colorSet.block.darken.HARDWARE,
        arrowColor: EntryStatic.colorSet.arrow["default"].HARDWARE,
        options: Entry.Diaboard.INEQ_SIGN,
        value: '<'
      }, {
        type: 'Block',
        accept: 'string'
      }],
      events: {},
      def: {
        params: [null, null, {
          type: 'text',
          params: ['100']
        }],
        type: 'diaboard_sensor_condition'
      },
      paramsKeyMap: {
        SENSOR: 0,
        INEQ_SIGN: 1,
        VALUE: 2
      },
      "class": 'condition',
      isNotFor: ['diaboard'],
      func: function func(sprite, script) {
        var sensor = script.getStringField('SENSOR');
        var ineqSign = script.getStringField('INEQ_SIGN');
        var value = script.getNumberValue('VALUE');
        value = isNaN(value) ? 0 : value;
        if (sensor == 'ir') {
          var irValue = Entry.hw.portData['S6'];
          if (ineqSign == '<' && irValue < value) {
            return true;
          } else if (ineqSign == '>' && irValue > value) {
            return true;
          } else if (ineqSign == '=' && irValue == value) {
            return true;
          } else {
            return false;
          }
        } else if (sensor == 'brightness') {
          var brightnessValue = Entry.hw.portData['S8'];
          if (ineqSign == '<' && brightnessValue < value) {
            return true;
          } else if (ineqSign == '>' && brightnessValue > value) {
            return true;
          } else if (ineqSign == '=' && brightnessValue == value) {
            return true;
          } else {
            return false;
          }
        } else {
          return false;
        }
      },
      syntax: {
        js: [],
        py: ['Diaboard.sensor_condition(%1,%2,%3)']
      }
    },
