    diaboard_convert_scale: {
      color: EntryStatic.colorSet.block["default"].HARDWARE,
      outerLine: EntryStatic.colorSet.block.darken.HARDWARE,
      fontColor: '#fff',
      skeleton: 'basic_string_field',
      statements: [],
      params: [{
        type: 'Dropdown',
        fontSize: 11,
        bgColor: EntryStatic.colorSet.block.darken.HARDWARE,
        arrowColor: EntryStatic.colorSet.arrow["default"].HARDWARE,
        options: options_DIABOARD_sensor,
        value: 'ir'
      }, {
        type: 'Block',
        accept: 'string'
      }, {
        type: 'Block',
        accept: 'string'
      }, {
        type: 'Block',
        accept: 'string'
      }, {
        type: 'Block',
        accept: 'string'
      }],
      events: {},
      def: {
        params: [null, {
          type: 'text',
          params: ['0']
        }, {
          type: 'text',
          params: ['1023']
        }, {
          type: 'text',
          params: ['0']
        }, {
          type: 'text',
          params: ['100']
        }],
        type: 'diaboard_convert_scale'
      },
      paramsKeyMap: {
        SENSOR: 0,
        VALUE1: 1,
        VALUE2: 2,
        VALUE3: 3,
        VALUE4: 4
      },
      "class": 'condition',
      isNotFor: ['diaboard'],
      func: function func(sprite, script) {
        var sensor = script.getStringField('SENSOR');
        var in_min = script.getNumberValue('VALUE1');
        var in_max = script.getNumberValue('VALUE2');
        var out_min = script.getNumberValue('VALUE3');
        var out_max = script.getNumberValue('VALUE4');
        in_min = isNaN(in_min) ? 0 : in_min;
        in_max = isNaN(in_min) ? 0 : in_max;
        out_min = isNaN(in_min) ? 0 : out_min;
        out_max = isNaN(in_min) ? 0 : out_max;
        if (sensor == 'ir') {
          var irSensor = Entry.hw.portData['S5'];
          var irValue = Entry.hw.portData['S6'];
          var v = (irValue - in_min) * (out_max - out_min) / (in_max - in_min) + out_min;
          return v.toString();
        } else if (sensor == 'brightness') {
          var brightnessSensor = Entry.hw.portData['S7'];
          var brightnessValue = Entry.hw.portData['S8'];
          var _v = (brightnessValue - in_min) * (out_max - out_min) / (in_max - in_min) + out_min;
          return _v.toString();
        } else {
          return "0";
        }
      },
      syntax: {
        js: [],
        py: ['Diaboard.convert_scale(%1, %2, %3, %4, %5)']
      }
    },
