    diaboard_led_hue: {
      color: EntryStatic.colorSet.block["default"].HARDWARE,
      outerLine: EntryStatic.colorSet.block.darken.HARDWARE,
      skeleton: 'basic',
      statements: [],
      params: [{
        type: 'Dropdown',
        fontSize: 11,
        bgColor: EntryStatic.colorSet.block.darken.HARDWARE,
        arrowColor: EntryStatic.colorSet.arrow["default"].HARDWARE,
        options: options_DIABOARD_led,
        value: 0
      }, {
        type: 'Block',
        accept: 'string'
      }, {
        type: 'Indicator',
        img: 'block_icon/hardware_icon.svg',
        size: 12
      }],
      events: {},
      def: {
        params: [null, {
          type: 'text',
          params: ['0']
        }, null],
        type: 'diaboard_led_hue',
        id: 'i3je'
      },
      paramsKeyMap: {
        LED: 0,
        HUE: 1
      },
      "class": 'led',
      isNotFor: ['diaboard'],
      func: function func(sprite, script) {
        var led = script.getNumberValue('LED');
        if (led == 7) {
          // 7은 랜덤
          led = Math.floor(Math.random() * 6) + 1; // 1 ~ 6
        }
        var hue = script.getNumberValue('HUE');
        hue = isNaN(hue) || hue < 0 ? 0 : hue;
        hue = Math.floor(hue % 360); // 0 ~ 359 범위로 조정하기
        var r_value = 0;
        var g_value = 0;
        var b_value = 0;
        if (hue <= 120) {
          r_value = 120 - hue;
          g_value = hue;
          b_value = 0;
        } else if (hue <= 240) {
          r_value = 0;
          g_value = 240 - hue;
          b_value = hue - 120;
        } else {
          r_value = hue - 240;
          g_value = 0;
          b_value = 360 - hue;
        }
        var time = 0;
        var cmd = "l:c:".concat(led, ":").concat(r_value, ":").concat(g_value, ":").concat(b_value, ":").concat(time); // l:x:c:255:255:255:1
        Entry.Diaboard.fireCommand(cmd);
        return Entry.Diaboard.deferredReturn(script.callReturn);
      },
      syntax: {
        js: [],
        py: ['Diaboard.led_hue(%1,%2)']
      }
    },
