Entry.KamibotPi = {
  id: '42.2',
  name: 'kamibotPi',
  url: 'http://www.kamibot.com/',
  imageName: 'kamibotPi.png',
  title: {
    ko: '카미봇Pi',
    en: 'KamibotPi'
  },
  moveSpeed: 100,
  getHashKey: function getHashKey() {
    var key = new Date().getSeconds().toString(16);
    if (key.length === 1) {
      key += (Math.random() * 16 | 0).toString(16);
    }
    return Entry.generateHash() + key;
  },
  /**
   * 정지버튼을 누르면 실행
   */
  setZero: function setZero() {
    var sq = Entry.hw.sendQueue;
    var pd = Entry.hw.portData;
    var msgId = Entry.KamibotPi.getHashKey();
    sq.msg_id = msgId;
    var msg = {
      id: msgId,
      type: COMMAND_TYPE.EMERGENCY_STOP,
      data: {},
      time: Date.now()
    };
    sq.msg = msg;
    Entry.hw.update(); // 해당 데이터를 하드웨어에 전달한다.
  },
  clamp: function clamp(n, min, max) {
    return Math.min(Math.max(n, min), max);
  }
};
