    practical_course_diode_secs_toggle: {
      color: '#ff8d0f',
      outerLine: '#e37100',
      skeleton: 'basic',
      fontColor: '#fff',
      statements: [],
      isNotFor: ['neobot'],
      template: '%1번 포트의 발광다이오드를 %2초 동안 %3 %4',
      params: [{
        type: 'Dropdown',
        options: [['OUT 1', '1'], ['OUT 2', '2'], ['OUT 3', '3']],
        value: '1',
        fontSize: 11,
        bgColor: '#e37100',
        arrowColor: EntryStatic.colorSet.common.WHITE
      }, {
        type: 'Block',
        accept: 'string'
      }, {
        type: 'Dropdown',
        options: [['켜기', '255'], ['끄기', '0']],
        value: '255',
        fontSize: 11,
        bgColor: '#e37100',
        arrowColor: EntryStatic.colorSet.common.WHITE
      }, {
        type: 'Indicator',
        img: 'block_icon/practical_course/diode.png',
        size: 12
      }],
      events: {},
      def: {
        params: [null, {
          type: 'number',
          params: ['2']
        }, null, null],
        type: 'practical_course_diode_secs_toggle'
      },
      paramsKeyMap: {
        PORT: 0,
        DURATION: 1,
        VALUE: 2
      },
      "class": 'practical_course_diode',
      func: function func(sprite, script) {
        if (!script.isStart) {
          var port = script.getNumberField('PORT');
          var duration = script.getNumberValue('DURATION');
          var value = script.getNumberField('VALUE');
          var option = port;
          if (value < 0) {
            value = 0;
          } else if (value > 255) {
            value = 255;
          }
          if (option === 3) {
            option = 4;
          }
          script.isStart = true;
          script.timeFlag = 1;
          script.outPort = port;
          script.outOption = option;
          Entry.hw.sendQueue["OUT".concat(port)] = value;
          Entry.hw.sendQueue.OPT = Entry.hw.sendQueue.OPT & ~option;
          setTimeout(function () {
            script.timeFlag = 0;
          }, duration * 1000);
          return script;
        } else if (script.timeFlag == 1) {
          return script;
        } else {
          Entry.hw.sendQueue["OUT".concat(script.outPort)] = 0;
          Entry.hw.sendQueue.OPT = Entry.hw.sendQueue.OPT & ~script.outOption;
          delete script.timeFlag;
          delete script.isStart;
          delete script.outPort;
          delete script.outOption;
          Entry.engine.isContinue = false;
          return script.callReturn();
        }
      }
    },
