    neobot_purple_led_on: {
      color: EntryStatic.colorSet.block["default"].HARDWARE,
      outerLine: EntryStatic.colorSet.block.darken.HARDWARE,
      skeleton: 'basic',
      statements: [],
      params: [{
        type: 'Dropdown',
        options: [['OUT1', 'OUT1'], ['OUT2', 'OUT2'], ['OUT3', 'OUT3'], [Lang.Blocks.neobot_purple_out_all, 'ALL']],
        value: 'OUT1',
        fontSize: 11,
        bgColor: EntryStatic.colorSet.block.darken.HARDWARE,
        arrowColor: EntryStatic.colorSet.arrow["default"].HARDWARE
      }, {
        type: 'Dropdown',
        options: [['100%', '255'], ['90%', '230'], ['80%', '204'], ['70%', '179'], ['60%', '153'], ['50%', '128'], ['40%', '102'], ['30%', '77'], ['20%', '51'], ['10%', '26']],
        value: '255',
        fontSize: 11,
        bgColor: EntryStatic.colorSet.block.darken.HARDWARE,
        arrowColor: EntryStatic.colorSet.arrow["default"].HARDWARE
      }, {
        type: 'Block',
        accept: 'string',
        defaultType: 'number'
      }, {
        type: 'Indicator',
        img: 'block_icon/hardware_icon.svg',
        size: 12
      }],
      events: {},
      def: {
        params: [null, null, {
          type: 'neobot_purple_arg_led_duration',
          id: 'm311'
        }, null],
        type: 'neobot_purple_led_on'
      },
      paramsKeyMap: {
        PORT: 0,
        VALUE: 1,
        DURATION: 2
      },
      "class": 'neobot_purple_led',
      isNotFor: ['neobot_purple'],
      func: function func(sprite, script) {
        if (!script.isStart) {
          var port = script.getStringField('PORT', script);
          var value = script.getNumberField('VALUE', script);
          var duration = script.getStringValue('DURATION', script);
          if (Entry.NeobotPurple.log_to_console) {
            Entry.console.print('=== neobot_purple_led_on ===', 'speak');
            Entry.console.print('port : ' + port, 'speak');
            Entry.console.print('brightness : ' + value, 'speak');
            Entry.console.print('duration : ' + duration, 'speak');
            Entry.console.print('==========================', 'speak');
          }
          if (duration != '계속' && duration != 'constantly' && Entry.parseNumber(duration) <= 0) {
            return script.callReturn();
          }
          if (port == 'ALL') {
            Entry.hw.sendQueue['OUT1'] = value;
            Entry.hw.sendQueue['OUT2'] = value;
            Entry.hw.sendQueue['OUT3'] = value;
          } else {
            Entry.hw.sendQueue[port] = value;
          }
          if (duration == '계속' || duration == 'constantly') {
            return script.callReturn();
          }
          var durationValue = Entry.parseNumber(duration);
          script.isStart = true;
          script.timeFlag = 1;
          setTimeout(function () {
            if (port == 'ALL') {
              Entry.hw.sendQueue['OUT1'] = 0;
              Entry.hw.sendQueue['OUT2'] = 0;
              Entry.hw.sendQueue['OUT3'] = 0;
            } else {
              Entry.hw.sendQueue[port] = 0;
            }
            if (Entry.NeobotPurple.log_to_console) Entry.console.print('neobot_purple_led_on : 0', 'speak');
            script.timeFlag = 0;
          }, durationValue * 1000);
          return script;
        } else if (script.timeFlag == 1) {
          return script;
        } else {
          delete script.timeFlag;
          delete script.isStart;
          Entry.engine.isContinue = false;
          return script.callReturn();
        }
      }
    },
