        options: [[Lang.Blocks.neobot_think_car_color_white, 0], [Lang.Blocks.neobot_think_car_color_red, 1], [Lang.Blocks.neobot_think_car_color_yellow, 2], [Lang.Blocks.neobot_think_car_color_green, 3], [Lang.Blocks.neobot_think_car_color_blue, 4]],
        value: '0',
        fontSize: 11,
