              var cubeId = Entry.PingpongG2._getCubeNoFromBlock(script);
              var str = script.getStringValue('STR', script);
              var duration = script.getNumberValue('DURATION', script);
              var period = Math.round(duration * 100 / (str.length * 8));
              period = Math.min(Math.max(period, 1), 200);
              var opt = Buffer.concat([Buffer.from([0x70, period, 0]), Buffer.from(str.substring(0, 20))]);
              var packet = Entry.PingpongG2.makePacket(OPCODE.LEDMATRIX, 0xe3, cubeId, opt);
              // add delay time for matrix stability (about 400ms)
              var waitTime = period * (str.length + 1) * 8 * 10 + 400;
              return [packet, waitTime];
