    // 아날로그 입력 값 맵핑 블럭
    connect_value_mapping: {
      color: EntryStatic.colorSet.block["default"].HARDWARE,
      outerLine: EntryStatic.colorSet.block.darken.HARDWARE,
      fontColor: '#ffffff',
      skeleton: 'basic_string_field',
      params: [{
        type: 'Block',
        accept: 'string'
      }, {
        type: 'Block',
        accept: 'string'
      }, {
        type: 'Block',
        accept: 'string'
      }, {
        type: 'Block',
        accept: 'string'
      }, {
        type: 'Block',
        accept: 'string'
      }],
      def: {
        params: [
        // Dropdown 값의 경우 Value를 세팅하면 초기값이 처리 됩니다.
        '0', '0', '0', '0', '0'],
        type: 'connect_value_mapping'
      },
      paramsKeyMap: {
        DATA: 0,
        SOURCE1: 1,
        SOURCE2: 2,
        TARGET1: 3,
        TARGET2: 4
      },
      "class": 'input',
      isNotFor: ['ProboConnect'],
      func: function func(sprite, script) {
        var data = script.getNumberValue('DATA', script);
        var source1 = script.getNumberValue('SOURCE1', script);
        var source2 = script.getNumberValue('SOURCE2', script);
        var target1 = script.getNumberValue('TARGET1', script);
        var target2 = script.getNumberValue('TARGET2', script);
        var value = 0;
        var rate = (data - source1) / (source2 - source1);
        var num = 0;
        if (target1 < target2) {
          value = (target2 - target1) * rate;
          num = value % 1;
          if (num < 0.5) value -= num;else value += 1 - num;
          value = target1 + value;
          if (value < target1) value = target1;else if (value > target2) value = target2;
        } else {
          value = (target1 - target2) * rate;
          num = value % 1;
          if (num < 0.5) value -= num;else value += 1 - num;
          value = target1 - value;
          if (value > target1) value = target1;else if (value < target2) value = target2;
        }
        return value;
      }
    },
