    robolink_codrone_diy_drone_trim_direction: {
      color: EntryStatic.colorSet.block["default"].HARDWARE,
      outerLine: EntryStatic.colorSet.block.darken.HARDWARE,
      skeleton: 'basic',
      statements: [],
      params: [{
        type: 'Dropdown',
        options: [[Lang.Blocks.drone_trim_pitch_increase, 'pitch_inc'], [Lang.Blocks.drone_trim_pitch_decrease, 'pitch_dec'], [Lang.Blocks.drone_trim_roll_increase, 'roll_inc'], [Lang.Blocks.drone_trim_roll_decrease, 'roll_dec'], [Lang.Blocks.drone_trim_reset, 'reset']],
        value: 'pitch_inc',
        fontSize: 11,
        bgColor: EntryStatic.colorSet.block.darken.HARDWARE,
        arrowColor: EntryStatic.colorSet.arrow["default"].HARDWARE
      }, {
        type: 'Indicator',
        img: 'block_icon/hardware_icon.svg',
        size: 12
      }],
      events: {},
      def: {
        params: [null, null],
        type: 'robolink_codrone_diy_drone_trim_direction'
      },
      paramsKeyMap: {
        DIRECTION: 0
      },
      "class": 'trim',
      isNotFor: ['robolink_codrone_diy'],
      func: function func(sprite, script) {
        var direction = script.getField('DIRECTION');
        var r = Entry.hw.portData['trim_roll'];
        var p = Entry.hw.portData['trim_pitch'];
        var y = Entry.hw.portData['trim_yaw'];
        var t = Entry.hw.portData['trim_throttle'];
        var interval = 5;
        switch (direction) {
          case 'pitch_inc':
            {
              p = p + interval;
            }
            break;
          case 'pitch_dec':
            {
              p = p - interval;
            }
            break;
          case 'roll_inc':
            {
              r = r + interval;
            }
            break;
          case 'roll_dec':
            {
              r = r - interval;
            }
            break;
          case 'reset':
            {
              r = 0;
              p = 0;
              y = 0;
              t = 0;
            }
            break;
          default:
            break;
        }
        return Entry.byrobot_base.sendTrim(script, 0x10, r, p, y, t);
      }
    },
