  /***************************************************************************************
   *  기능
   ***************************************************************************************/
  // 데이터 읽기
  getData: function getData(script, device) {
    return Entry.hw.portData[device];
  },
  getRgbFromString: function getRgbFromString(stringColor) {
    var red = 0;
    var green = 0;
    var blue = 0;
    switch (stringColor) {
      case 'red':
        {
          red = 255;
          green = 0;
          blue = 0;
        }
        break;
      case 'green':
        {
          red = 0;
          green = 255;
          blue = 0;
        }
        break;
      case 'blue':
        {
          red = 0;
          green = 0;
          blue = 255;
        }
        break;
      case 'cyan':
        {
          red = 0;
          green = 255;
          blue = 255;
        }
        break;
      case 'magenta':
        {
          red = 255;
          green = 0;
          blue = 255;
        }
        break;
      case 'yellow':
        {
          red = 255;
          green = 255;
          blue = 0;
        }
        break;
      case 'white':
        {
          red = 255;
          green = 255;
          blue = 255;
        }
        break;
      case 'sunset':
        {
          red = 255;
          green = 100;
          blue = 0;
        }
        break;
      case 'cottonCandy':
        {
          red = 20;
          green = 250;
          blue = 150;
        }
        break;
      case 'muscat':
        {
          red = 70;
          green = 255;
          blue = 0;
        }
        break;
      case 'strawberryMilk':
        {
          red = 150;
          green = 60;
          blue = 20;
        }
        break;
      case 'emerald':
        {
          red = 0;
          green = 255;
          blue = 30;
        }
        break;
      case 'lavender':
        {
          red = 80;
          green = 0;
          blue = 200;
        }
        break;
    }
    return {
      r: red,
      g: green,
      b: blue
    };
  },
