HamsterSRobot.prototype.gripper = function (script) {
  var self = this;
  self.__setModule();
  if (!script.isStart) {
    script.isStart = true;
    script.isPlaying = true;
    self.__cancelIo();
    var id = self.__issueIoBlockId();
    var action = script.getField('ACTION');
    var motoring = this.motoring;
    motoring.ioModeA = 10;
    motoring.ioModeB = 10;
    if (action == 'OPEN') {
      motoring.outputA = 1;
      motoring.outputB = 0;
    } else {
      motoring.outputA = 0;
      motoring.outputB = 1;
    }
    self.ioTimer = setTimeout(function () {
      if (self.ioBlockId == id) {
        self.__cancelIo();
        script.isPlaying = false;
      }
    }, 500);
    self.timeouts.push(self.ioTimer);
    return script;
  } else if (script.isPlaying) {
    return script;
  } else {
    delete script.isStart;
    delete script.isPlaying;
    Entry.engine.isContinue = false;
    return script.callReturn();
  }
};
