CheeseRobot.prototype.writeSerial = function (script) {
  var self = this;
  self.__setModule();
  if (!script.isStart) {
    script.isStart = true;
    script.isWriting = true;
    var mode = script.getField('MODE');
    var text = script.getValue('STRING');
    this.__setSerialModePid();
    var queue = this.writeQueue;
    queue.push(text, mode != 'STRING');
    var data = queue.pop();
    if (data) {
      this.writeSerialCallbacks.push(function () {
        script.isWriting = false;
      });
      this.__setSerial(data);
    } else {
      script.isWriting = false;
    }
    return script;
  } else if (script.isWriting) {
    return script;
  } else {
    delete script.isStart;
    delete script.isWriting;
    Entry.engine.isContinue = false;
    return script.callReturn();
  }
};
