CheeseRobot.prototype.pidStart = function (script) {
  this.__setModule();
  var dev = script.getField('DEVICE');
  switch (dev) {
    case '10':
      // PID-10 ultrasonic sensor (HC-SR04+)
      // 0: La(trigger) Lb(echo) Lc(GND)
      // 1: La(trigger) Lb(echo)
      this.motoring.outputLa = 0;
      this.__setModeLa(255);
      this.__setModePid(10);
      break;
    case '11-1':
      // PID-11-1 humidity/temperature sensor (DHT11)
      // upper 4bits
      // 0: La(data)
      // 1: La(data), Lb(GND)
      // 2: La(data), Lb(VCC)
      this.motoring.outputLa = 1;
      this.__setModeLa(255);
      this.__setModePid(11);
      break;
    case '11-2':
      // PID-11-2 humidity/temperature sensor (DHT21)
      // upper 4bits
      // 0: La(data)
      // 1: La(data), Lb(GND)
      // 2: La(data), Lb(VCC)
      this.motoring.outputLa = 2;
      this.__setModeLa(255);
      this.__setModePid(11);
      break;
    case '11-3':
      // PID-11-3 humidity/temperature sensor (DHT22)
      // upper 4bits
      // 0: La(data)
      // 1: La(data), Lb(GND)
      // 2: La(data), Lb(VCC)
      this.motoring.outputLa = 3;
      this.__setModeLa(255);
      this.__setModePid(11);
      break;
    case '12':
      // PID-12 temperature sensor (DS18B20)
      this.__setModePid(12);
      break;
    case '13':
      // PID-13 joystick and button
      this.__setModePid(13);
      break;
    case '14':
      // PID-14 dual joystick
      this.__setModePid(14);
      break;
    case '15':
      // PID-15 IR transceiver
      this.__setModePid(15);
      break;
    case '16':
      // PID-16 encoder
      this.__setModePid(16);
      this.__resetEncoder();
      break;
  }
  return script.callReturn();
};
