    robotis_move_for_secs_dream: {
      color: '#00B200',
      outerLine: '#019101',
      skeleton: 'basic',
      fontColor: '#fff',
      statements: [],
      isNotFor: ['robotis_Dream'],
      template: '%1모터를 %2 %3의 속도로 %4초 동안 회전 %5',
      params: [{
        type: 'Dropdown',
        options: [['1번 포트', '1'], ['2번 포트', '2']],
        value: '1',
        fontSize: 11,
        bgColor: '#019101',
        arrowColor: EntryStatic.colorSet.common.WHITE
      }, {
        type: 'Dropdown',
        options: [['시계방향', 'CW'], ['반시계방향', 'CCW']],
        value: 'CW',
        fontSize: 11,
        bgColor: '#019101',
        arrowColor: EntryStatic.colorSet.common.WHITE
      }, {
        type: 'Block',
        accept: 'string'
      }, {
        type: 'Block',
        accept: 'string'
      }, {
        type: 'Indicator',
        img: 'block_icon/practical_course/dcmotor.png',
        size: 12
      }],
      events: {},
      def: {
        params: [null, null, {
          type: 'practical_course_motor_speed'
        }, {
          type: 'number',
          params: ['2']
        }, null],
        type: 'robotis_move_for_secs_dream'
      },
      paramsKeyMap: {
        WHEEL: 0,
        DIRECTION: 1,
        SPEED: 2,
        DURATION: 3
      },
      "class": 'robotis_motor',
      func: function func(sprite, script) {
        Entry.hw.sendQueue.IS_EDU = true;
        var duration = script.getNumberValue('DURATION');
        var wheel = script.getNumberField('WHEEL');
        var value = script.getNumberValue('SPEED');
        var direction = script.getStringField('DIRECTION');
        var data_instruction = Entry.Robotis_DREAM.INSTRUCTION.WRITE;
        // let data_address = 0;
        var data_address = data_address = Entry.Robotis_DREAM.CONTROL_TABLE.AUX_MOTOR_SPEED[0];
        var data_length = 0;
        var data_value = 0;

        //data_address = Entry.Robotis_DREAM.CONTROL_TABLE.AUX_MOTOR_SPEED[0];

        if (wheel == '3') {
          data_length = 4;
          // data_address = Entry.Robotis_DREAM.CONTROL_TABLE.AUX_MOTOR_SPEED[0];
        } else {
          data_length = Entry.Robotis_DREAM.CONTROL_TABLE.AUX_MOTOR_SPEED[1];
          data_address = data_address + (wheel - 1) * data_length;
        }
        if (!script.isStart) {
          value = value * 68;
          if (direction == 'CW') {
            value = value + 1024;
            if (value > 2047) {
              value = 2047;
            }
          } else {
            if (value > 1023) {
              value = 1023;
            }
          }
          /*if (wheel == '3' || wheel == '1') {
              if (direction == 'CCW') {
                  value = value + 1024;
                  if (value > 2047) {
                      value = 2047;
                  }
              } else {
                  if (value > 1023) {
                      value = 1023;
                  }
              }
          } else {
              if (direction == 'CW') {
                  value = value + 1024;
                  if (value > 2047) {
                      value = 2047;
                  }
              } else {
                  if (value > 1023) {
                      value = 1023;
                  }
              }
          }*/

          data_value = value;
          var data_sendqueue = [[data_instruction, data_address, data_length, data_value]];
          script.wheelMode = wheel;
          script.isStart = true;
          script.timeFlag = 1;
          setTimeout(function () {
            script.timeFlag = 0;
          }, duration * 1000);
          Entry.Robotis_DREAM.setRobotisData(data_sendqueue);
          Entry.Robotis_DREAM.update();
          //return Entry.Robotis_carCont.postCallReturn(script, data_sendqueue, 2000);
          return script;
        } else if (script.timeFlag == 1) {
          //data_sendqueue = [[data_instruction, data_address, data_length, 0]];
          //Entry.Robotis_carCont.setRobotisData(data_sendqueue);
          return script;
        } else {
          delete script.timeFlag;
          delete script.isStart;
          delete script.wheelMode;
          Entry.engine.isContinue = false;
          data_sendqueue = [[data_instruction, data_address, data_length, 0]];
          Entry.Robotis_DREAM.setRobotisData(data_sendqueue);
          Entry.engine.isContinue = false;
          Entry.Robotis_DREAM.update();
          return script.callReturn();
        }
        //return Entry.Robotis_carCont.postCallReturn(script, data_sendqueue, 2000);
      }
    },
