        var direction = script.getNumberValue('DIRECTION', script);
        angle *= direction;
        if (angle > 720) {
          angle = 720;
        } else if (angle < -720) {
          angle = -720;
        }
        var data_instruction = Entry.Robotis_rb.INSTRUCTION.WRITE;
        var data_address = 270;
        var data_length = 4;
        var data_value = Math.floor(angle);
        var data_sendqueue = [[data_instruction, data_address, data_length, data_value]];
        data_sendqueue.push([data_instruction, 66, 2, 50492]);
        return Entry.Robotis_carCont.postCallReturn(script, data_sendqueue, Entry.Robotis_openCM70.delay + Math.abs(angle) * 16 + 1500
        //Entry.Robotis_openCM70.delay
        );
