    robotis_Practice_detectFrontObj: {
      color: EntryStatic.colorSet.block["default"].HARDWARE,
      outerLine: EntryStatic.colorSet.block.darken.HARDWARE,
      fontColor: '#fff',
      skeleton: 'basic_boolean_field',
      statements: [],
      params: [{
        type: 'Dropdown',
        options: [[Lang.Blocks.robotis_front_ir_sensor, '0'], [Lang.Blocks.robotis_distance_sensor, '1']],
        value: '0',
        fontSize: 11,
        bgColor: EntryStatic.colorSet.block.darken.HARDWARE,
        arrowColor: EntryStatic.colorSet.arrow["default"].HARDWARE
      }, {
        type: 'Dropdown',
        options: [[Lang.Blocks.robotis_front, '0'], [Lang.Blocks.robotis_right, '1'], [Lang.Blocks.robotis_left, '2']],
        value: '0',
        fontSize: 11,
        bgColor: EntryStatic.colorSet.block.darken.HARDWARE,
        arrowColor: EntryStatic.colorSet.arrow["default"].HARDWARE
      }],
      events: {},
      def: {
        params: [null, null],
        type: 'robotis_Practice_detectFrontObj'
      },
      paramsKeyMap: {
        SENSOR: 0,
        DIRECTION: 1
      },
      "class": 'robotis_rb100_custom',
      isNotFor: ['Robotis_rb_P_Assembly'],
      func: function func(sprite, script) {
        var scope = script.executor.scope;

        // instruction / address / length / value / default length
        var data_instruction = Entry.Robotis_rb.INSTRUCTION.READ;
        var data_address = 360;
        var data_length = 4;
        var data_value = 0;
        var data_default_address = 0;
        var data_default_length = 0;
        var sensorType = script.getNumberValue('SENSOR');
        var direction = script.getNumberValue('DIRECTION');
        var ir_1 = 0;
        var ir_2 = 0;
        if (sensorType == 0) {
          if (direction == 0) {
            ir_1 = Entry.hw.portData[360];
            ir_2 = Entry.hw.portData[362];
            if (ir_1 == undefined) ir_1 = 0;
            if (ir_2 == undefined) ir_2 = 0;
            return ir_1 > 100 || ir_2 > 100;
          } else if (direction == 1) {
            ir_1 = Entry.hw.portData[368];
            if (ir_1 == undefined) ir_1 = 0;
            return ir_1 > 100;
          } else if (direction == 2) {
            ir_1 = Entry.hw.portData[370];
            if (ir_1 == undefined) ir_1 = 0;
            return ir_1 > 100;
          }
        } else if (sensorType == 1) {
          data_instruction = Entry.Robotis_rb.INSTRUCTION.BYPASS_READ;
          data_address = 25;
          data_length = 2;
          data_value = 110; // id

          data_default_address = data_address;
          data_default_length = data_length;
          if (Entry.hw.sendQueue.prevAddress && Entry.hw.sendQueue.prevAddress == data_default_address) {
            if (Entry.hw.sendQueue.prevTime && new Date() - Entry.hw.sendQueue.prevTime < Entry.Robotis_openCM70.readDelay) {
              //throw new Entry.Utils.AsyncError();
              if (typeof Entry.hw.sendQueue.prevResult == 'undefined') {
                return false;
              }
              return Entry.hw.sendQueue.prevResult < 200;
            }
          }
          Entry.Robotis_carCont.setRobotisData([[data_instruction, data_address, data_length, data_value, data_default_length]]);
          // Entry.hw.socket.send(JSON.stringify(Entry.hw.sendQueue));
          Entry.Robotis_carCont.update();

          // 통합센서의 컨트롤 테이블 주소는 RB-100블록에서 사용하지 않는 주소를 사용
          // 주소 겹침 방지
          var result = Entry.hw.portData[data_default_address];
          if (result == undefined) {
            result = rb100_last_valid_value[data_default_address];
          } else {
            rb100_last_valid_value[data_default_address] = result;
          }
          Entry.hw.sendQueue.prevAddress = data_default_address;
          Entry.hw.sendQueue.prevTime = new Date();
          Entry.hw.sendQueue.prevResult = result;
          if (typeof result == 'undefined') {
            return false;
          } else {
            return result < 200;
          }
        }
      },
      syntax: {
        js: [],
        py: ['Robotis.RB_detectFrontObj()']
      }
    },
