        var text = script.getStringValue('TEXT', script);
        var x = script.getNumberValue('X', script);
        var y = script.getNumberValue('Y', script);
        var font = 0;
        var color = script.getNumberValue('COLOR', script);
        var data_buf = [];
        var i = 0;
        if (x < -160) x = -160;else if (x > 160) x = 160;
        if (y < -120) y = -120;else if (y > 120) y = 120;
        var encoder = new TextEncoder('utf-8');
        var byteArray = encoder.encode(text);
        data_buf.push(x % 256);
        data_buf.push(Math.floor(x / 256));
        data_buf.push(y % 256);
        data_buf.push(Math.floor(y / 256));
        data_buf.push(font);
        data_buf.push(1);
        data_buf.push(bg_color);
        data_buf.push(color);
        data_buf.push(byteArray.length);
        for (i = 0; i < byteArray.length; i++) {
          data_buf.push(byteArray[i]);
        }
        var data_instruction = Entry.Robotis_rb.INSTRUCTION.WRITE;
        var data_address = 900;
        var data_length = 9 + byteArray.length;
        var data_sendqueue = [[data_instruction, data_address, data_length, data_buf], [Entry.Robotis_rb.INSTRUCTION.WRITE, 162, 1, 1]];
        return Entry.Robotis_carCont.postCallReturn(script, data_sendqueue, Entry.Robotis_openCM70.delay + 100);
