      "class": 'robotis_openCM70_cm',
      isNotFor: ['Robotis_rb_P_Assembly'],
      func: function func(entity, script) {
        var data_instruction = Entry.Robotis_rb.INSTRUCTION.BYPASS_WRITE;
        var data_address = 0;
        var data_length = 0;
        data_address = Entry.Robotis_rb.CONTROL_TABLE.DXL_PROFILE_VELOCITY[0];
        data_length = Entry.Robotis_rb.CONTROL_TABLE.DXL_PROFILE_VELOCITY[1] + Entry.Robotis_rb.CONTROL_TABLE.DXL_GOAL_POSITION[1];
        var dxlID = script.getField('DXLNUM', script);
        var angle = script.getNumberValue('ANGLE', script);
        var time = script.getNumberValue('TIME', script) * 1000;
        var data_buf = [];
        var engValue = 2048;
        engValue = Math.floor(2048 - Math.round(angle * 4096) / 360);
        var velocity = 0;
        if (time == 0) {
          velocity = 0;
        } else {
          velocity = Math.round(Math.floor(60 * Math.abs(angle - Entry.Robotis_rb.DXL_POSITION.values[dxlID - 1]) * 1000 / 360 / time) / 0.229);
        }
        Entry.Robotis_rb.DXL_POSITION.values[dxlID - 1] = angle;
        data_buf.push(velocity % 256);
        data_buf.push(Math.floor(velocity / 256));
        data_buf.push(0);
        data_buf.push(0);
        data_buf.push(engValue % 256);
        data_buf.push(Math.floor(engValue / 256));
        data_buf.push(0);
        data_buf.push(0);
        var data_sendqueue = [[data_instruction, data_address, data_length, dxlID, data_buf]];
        return Entry.Robotis_carCont.postCallReturn(script, data_sendqueue, time + Entry.Robotis_openCM70.delay
        //Entry.Robotis_openCM70.delay
        );
      },
