        if (dxl_speed < 0) dxl_speed = 0;else if (dxl_speed > 100) dxl_speed = 100;
        data_value_2 = dxl_speed * 10;
        data_address_3 = Entry.Robotis_rb.CONTROL_TABLE.CM_DXL_MULTITURN_DISTANCE[0];
        data_length_3 = Entry.Robotis_rb.CONTROL_TABLE.CM_DXL_MULTITURN_DISTANCE[1];
