        data_value_3 = dxl_round * 4096;
        if (dxl_direction == 1) data_value_3 = -data_value_3;
        data_sendqueue = [[data_instruction, data_address_1, data_length_1, dxl_id], [data_instruction, data_address_2, data_length_2, data_value_2], [data_instruction, data_address_3, data_length_3, data_value_3]];
        return Entry.Robotis_carCont.postCallReturn(script, data_sendqueue, Entry.Robotis_openCM70.delay);
