    /* Paroduel Motor Start */
    Parodule_Motor: {
      color: EntryStatic.colorSet.block["default"].HARDWARE,
      outerLine: EntryStatic.colorSet.block.darken.HARDWARE,
      skeleton: 'basic',
      statements: [],
      params: [{
        type: 'Block',
        accept: 'string',
        defaultType: 'number'
      }, {
        type: 'Block',
        accept: 'string',
        defaultType: 'number'
      }, {
        type: 'Indicator',
        img: 'block_icon/hardware_dc.svg',
        size: 12
      }],
      events: {},
      def: {
        params: [{
          type: 'Parodule_Custom_Motor_List',
          params: [100]
        }, {
          type: 'Parodule_Motor_Sign',
          params: [0]
        }],
        type: 'Parodule_Motor'
      },
      paramsKeyMap: {
        POWER: 0,
        SIGNED: 1
      },
      "class": 'SET',
      isNotFor: ['Robotry_Parodule'],
      func: function func(sprite, script) {
        var power = script.getNumberValue('POWER');
        var sign = script.getNumberValue('SIGNED') % 4;
        var correction_power = power === 100 ? 39 : power === 75 ? 38 : power === 50 ? 37 : power === 25 ? 36 : 200;
        var normal = 0;
        var shift = 4; // 회전 반향 반전
        var motorR = 0;
        var motorL = 0;
        if (sign === 0) {
          motorR = normal;
          motorL = shift;
        } else if (sign === 1) {
          motorR = shift;
          motorL = normal;
        } else if (sign === 2) {
          motorR = normal;
          motorL = normal;
        } else if (sign === 3) {
          motorR = shift;
          motorL = shift;
        } else {}
        if (!Entry.hw.sendQueue.SET) {
          Entry.hw.sendQueue.SET = {};
        }
        if (correction_power === 200) {
          motorR = 0;
          motorL = 0;
        }
        for (var i = 0; i < 4; i++) {
          if (Entry.Robotry_Parodule.getTerminal(i) === Entry.Robotry_Parodule.moduleType.MOTOR) {
            if (i === 0 || i === 1) {
              Entry.hw.sendQueue.SET[i] = {
                type: Entry.Robotry_Parodule.controlTypes.DIGITAL,
                data: motorR + correction_power,
                time: new Date().getTime()
              };
            } else if (i === 2 || i === 3) {
              Entry.hw.sendQueue.SET[i] = {
                type: Entry.Robotry_Parodule.controlTypes.DIGITAL,
                data: motorL + correction_power,
                time: new Date().getTime()
              };
            } else {}
          }
        }
        return script.callReturn();
      },
      syntax: {
        js: [],
        py: [{
          syntax: 'Parodule.set_Motor(%1, %2)',
          textParams: [{
            type: 'Block',
            accept: 'string'
          }, {
            type: 'Block',
            accept: 'string'
          }]
        }]
      }
    },
    /* Parodule Motor End */

