      def: {
        params: [{
          type: 'thinkboard_analog_port_list'
        }, {
          type: 'thinkboard_analog_port_name'
        }, {
          type: 'number',
          params: ['0']
        }, {
          type: 'number',
          params: ['1023']
        }, {
          type: 'number',
          params: ['0']
        }, {
          type: 'number',
          params: ['100']
        }],
        type: 'thinkboard_get_analog_mapping'
      },
      paramsKeyMap: {
        PORT: 0,
        TYPE: 1,
        VALUE2: 2,
        VALUE3: 3,
        VALUE4: 4,
        VALUE5: 5
      },
      "class": 'ThinkBoard_ANA',
      isNotFor: ['ThinkBoard'],
      func: function func(sprite, script) {
        var port = script.getValue('PORT', script);
        var type = script.getValue('TYPE', script);
        var result = 0;
        var ANALOG = Entry.hw.portData.ANALOG;
        var value2 = script.getNumberValue('VALUE2', script);
        var value3 = script.getNumberValue('VALUE3', script);
        var value4 = script.getNumberValue('VALUE4', script);
        var value5 = script.getNumberValue('VALUE5', script);
        if (port[0] === 'A') {
          port = port.substring(1);
        }
        //[4/18]  result = ANALOG ? ANALOG[port] || 0 : 0;           
        if (type === "2") result = 1023 - ANALOG[port];else result = ANALOG[port];
        if (value2 > value3) {
          var swap = value2;
          value2 = value3;
          value3 = swap;
        }
        if (value4 > value5) {
          var swap = value4;
          value4 = value5;
          value5 = swap;
        }
        result -= value2;
        result = result * ((value5 - value4) / (value3 - value2));
        result += value4;
        result = Math.min(value5, result);
        result = Math.max(value4, result);
        return Math.round(result);
      },
      syntax: {
        js: [],
        py: []
      }
