          neobot_purple_lite_motor_start: {
            color: EntryStatic.colorSet.block["default"].HARDWARE,
            outerLine: EntryStatic.colorSet.block.darken.HARDWARE,
            skeleton: 'basic',
            statements: [],
            params: [{
              type: 'Dropdown',
              options: [[Lang.Blocks.neobot_purple_lite_motor_both, '1'], [Lang.Blocks.neobot_purple_lite_motor_left, '2'], [Lang.Blocks.neobot_purple_lite_motor_right, '3']],
              value: '1',
              fontSize: 11,
              bgColor: EntryStatic.colorSet.block.darken.HARDWARE,
              arrowColor: EntryStatic.colorSet.arrow["default"].HARDWARE
            }, {
              type: 'Dropdown',
              options: [[Lang.Blocks.neobot_purple_lite_direction_forward, '1'], [Lang.Blocks.neobot_purple_lite_direction_backward, '2'], [Lang.Blocks.neobot_purple_lite_direction_left, '3'], [Lang.Blocks.neobot_purple_lite_direction_right, '4']],
              value: '1',
              fontSize: 11,
              bgColor: EntryStatic.colorSet.block.darken.HARDWARE,
              arrowColor: EntryStatic.colorSet.arrow["default"].HARDWARE
            }, {
              type: 'Block',
              accept: 'string',
              defaultType: 'number'
            }, {
              type: 'Block',
              accept: 'string',
              defaultType: 'number'
            }, {
              type: 'Indicator',
              img: 'block_icon/hardwarelite_icon.svg',
              size: 12
            }],
            events: {},
            def: {
              params: [null, null, {
                type: 'neobot_purple_lite_arg_motor_speed',
                id: 'm411'
              }, {
                type: 'neobot_purple_lite_arg_motor_duration',
                id: 'm412'
              }, null],
              type: 'neobot_purple_lite_motor_start'
            },
            paramsKeyMap: {
              MOTOR: 0,
              DIRECTION: 1,
              SPEED: 2,
              DURATION: 3
            },
            "class": 'neobot_purple_lite_motor',
            isNotFor: ['NeobotPurpleLite'],
            func: function func(sprite, script) {
              if (!script.isStart) {
                var motor = script.getStringField('MOTOR', script);
                var direction = script.getStringField('DIRECTION', script);
                var speed = script.getStringValue('SPEED', script);
                var duration = script.getStringValue('DURATION', script);
                if (duration != '계속' && duration != 'constantly' && Entry.parseNumber(duration) <= 0) {
                  return script.callReturn();
                }
                var moveLeft = false;
                var moveRight = false;
                if (motor == 1) {
                  moveLeft = true;
                  moveRight = true;
                } else if (motor == 2) {
                  moveLeft = true;
                } else {
                  moveRight = true;
                }
                var leftDirectionValue;
                var rightDirectionValue;
                if (direction == 1) {
                  leftDirectionValue = 0x10;
                  rightDirectionValue = 0x10;
                } else if (direction == 2) {
                  leftDirectionValue = 0x20;
                  rightDirectionValue = 0x20;
                } else if (direction == 3) {
                  leftDirectionValue = 0x20;
                  rightDirectionValue = 0x10;
                } else {
                  leftDirectionValue = 0x10;
                  rightDirectionValue = 0x20;
                }

                // edited 210421, 0~100 을 0~15로 변환, 100 이상은 최대값(15)으로 처리함.
                var speedValue = 0;
                if (Entry.Utils.isNumber(speed)) {
                  speedValue = Entry.parseNumber(speed);
                } else {
                  speedValue = Entry.NeobotPurpleLite.localBuffer[speed];
                }
                speedValue = Math.max(speedValue, 0);
                speedValue = Math.min(speedValue, 100);
                speedValue = Math.ceil(speedValue / 100 * 15);
                var leftOutValue = leftDirectionValue + speedValue;
                var rightOutValue = rightDirectionValue + speedValue;
                if (Entry.NeobotPurpleLite.log_to_console) {
                  Entry.console.print('=== neobot_purple_lite_motor_start ===', 'speak');
                  Entry.console.print("motor : ".concat(motor), 'speak');
                  Entry.console.print("direction : ".concat(direction), 'speak');
                  Entry.console.print("speed : ".concat(speed), 'speak');
                  Entry.console.print("duration : ".concat(duration), 'speak');
                  Entry.console.print("left direction value : ".concat(leftDirectionValue), 'speak');
                  Entry.console.print("right direction value : ".concat(rightDirectionValue), 'speak');
                  Entry.console.print("speed value : ".concat(speedValue), 'speak');
                  Entry.console.print("left output value : ".concat(leftOutValue), 'speak');
                  Entry.console.print("right output value : ".concat(rightOutValue), 'speak');
                  Entry.console.print('==========================', 'speak');
                }
                if (moveLeft) {
                  Entry.NeobotPurpleLite.remoteBuffer.DCL = leftOutValue;
                }
                if (moveRight) {
                  Entry.NeobotPurpleLite.remoteBuffer.DCR = rightOutValue;
                }
                if (duration == '계속' || duration == 'constantly') {
                  return script.callReturn();
                }
                var durationValue = Entry.parseNumber(duration);
                script.isStart = true;
                script.timeFlag = 1;
                setTimeout(function () {
                  Entry.NeobotPurpleLite.remoteBuffer.DCL = 0;
                  Entry.NeobotPurpleLite.remoteBuffer.DCR = 0;
                  if (Entry.NeobotPurpleLite.log_to_console) {
                    Entry.console.print('neobot_purple_lite_motor_start : 0', 'speak');
                  }
                  script.timeFlag = 0;
                }, durationValue * 1000);
                return script;
              } else if (script.timeFlag == 1) {
                return script;
              } else {
                delete script.timeFlag;
                delete script.isStart;
                Entry.engine.isContinue = false;
                return script.callReturn();
              }
            }
          },
